}

## begin_srd_creature_attack
Reserve the attack cost, resolve targeting, then retain its real roll for reactions.
arguments: {
 actor_can_see_target: boolean
 advantage: boolean
 // Actual distance to this target in feet.
 attack_distance: number // >= 0
 attack_mode: "melee" | "ranged"
 // Signed d20 attack modifier from the admitted creature stat block or GM adaptation.
 attack_modifier: integer
 // Plain attack label from the admitted creature stat block or the GM's stated adaptation.
 attack_name: string
 attack_uses_weapon?: boolean
 // Damage dice only; select one exact enum value and do not include a modifier.
 damage_expression: "fixed-1" | "d4" | "d6" | "d8" | "d10" | "d12" | "2d4" | "2d6" | "2d8" | "2d10" | "2d12" | "3d10" | "3d6" | "5d6"
 // Signed flat damage modifier applied after the damage dice.
 damage_modifier: integer
 damage_type: "acid" | "bludgeoning" | "cold" | "fire" | "force" | "lightning" | "necrotic" | "piercing" | "poison" | "psychic" | "radiant" | "slashing" | "thunder"
 disadvantage: boolean
 fear_source_in_sight: boolean
 known_spell_effect?: boolean
 // Maximum ranged distance; for melee use the same value as normal_range.
 long_range: integer // >= 0
 minor_elementals_damage_type?: "acid" | "cold" | "fire" | "lightning"
 // Melee reach or normal ranged distance in feet from the stat block or stated adaptation.
 normal_range: integer // >= 0
 request_after_hit_smite?: boolean
 // Exact authoritative entity ID of the living attack target; do not use its display name.
 target: string // a entity id
 target_can_see_actor: boolean
 target_is_charmer: boolean
 // Use a remaining named component of the creature's prepared Multiattack; true on every attack in that routine.
 use_multiattack?: boolean
 witness_state_ids?: string[]
}

## spend_srd_resource
Spend a package-owned resource. For class Hit Dice, select hit_die_class for a partial change; restoring the full total restores every class pool. For Action Surge, call use_srd_action_surge instead: it also grants the action.
arguments: {
 amount: integer // >= 1
 hit_die_class?: string
 resource: "action_surge" | "arcane_recovery" | "bardic_inspiration" | "channel_divinity" | "focus_point" | "hit_die" | "indomitable" | "second_wind" | "wholeness_of_body" | "spell_slot_1" | "spell_slot_2" | "spell_slot_3" | "spell_slot_4" | "spell_slot_5" | "spell_slot_6" | "spell_slot_7" | "spell_slot_8" | "spell_slot_9"
 // Exact state entity ID for target from SYLVIA_GM_CAMPAIGN_PREPARATION or SYLVIA_GM_FRESH_CAMPAIGN_STATE; never use a display name.
 target: string // a entity id
}

## restore_srd_resource
Restore a package-owned resource. For class Hit Dice, select hit_die_class for a partial change; restoring the full total restores every class pool.
arguments: {
 amount: integer // >= 1
 hit_die_class?: string
 resource: "action_surge" | "arcane_recovery" | "bardic_inspiration" | "channel_divinity" | "focus_point" | "hit_die" | "indomitable" | "second_wind" | "wholeness_of_body" | "spell_slot_1" | "spell_slot_2" | "spell_slot_3" | "spell_slot_4" | "spell_slot_5" | "spell_slot_6" | "spell_slot_7" | "spell_slot_8" | "spell_slot_9"
 // Exact state entity ID for target from SYLVIA_GM_CAMPAIGN_PREPARATION or SYLVIA_GM_FRESH_CAMPAIGN_STATE; never use a display name.
 target: string // a entity id
}

## prepare_srd_spells
At an earned rest's completion, apply the player's chosen replacement spells for one saved source. Preserve its cantrip and leveled-spell counts. Source rules enforce replacement limits and Wizard spellbook access; other grants and resource uses remain intact.
arguments: {
 // Exact participant_id for caster from SYLVIA_GM_CAMPAIGN_PREPARATION or SYLVIA_GM_FRESH_CAMPAIGN_STATE; never use a display name.
 caster: string // a participant id
 // Exact state entity ID for caster_state from SYLVIA_GM_CAMPAIGN_PREPARATION or SYLVIA_GM_FRESH_CAMPAIGN_STATE; never use a display name.
 caster_state: string // a entity id
 source: string
 // For Wizard preparation, confirm the character can access and study their spellbook.
 spellbook_available?: boolean
 // Complete replacement list for this source, including its unchanged spells and cantrips.
 spells: string[] // min items 1; max items 200; unique
}

## start_combat_encounter_entities
Roll Initiative and establish an encounter between two canonical creature states. When combat is inactive and the player declares a hostile weapon attack against a known present creature, including a companion, you MUST call this operation before any player-facing prose and before resolving the attack, then follow the freshly exposed combat lifecycle and weapon-attack operations. Do not decide in prose that the attack misses, is deflected, or is de-escalated. Do not restate the scene or ask what the player does instead. Do not substitute an Athletics or other skill check for the attack. Coordinate combat requires a saved spatial scene. For the first encounter, supply one scene in combat_scenes using the spatial_scene format 1 content definition: format=1; map with id, revision, bounds.min/max (three coordinates), grid.cell_size/unit='ft'/origin (two coordinates), and layers (id/min_elevation/max_elevation); entities, geometry, zones and terrain arrays. Each combatant needs exactly one active creature body: id, map_id, position (three coordinates), footprint (box.half_extents or circle.radius), height, facing (two coordinates), active, movement, visibility, and metadata with participant_ref equal to its saved actor ID, creature_type, plane and lighting. Choose physical positions and body dimensions from the encounter fiction; do not invent a target-distance substitute. Include known blockers and terrain. Declare metadata.player.label/kind only on bodies and geometry the player knows. Coordinate combat uses the saved spatial scene. Supply one combat_scenes entry when admitting a later roster or an actual new arena. Omit it to reuse the scene. For the same map ID, keep the existing bounds, grid and layers: all saved bodies, objects, blockers, zones and terrain remain authoritative; supplied rows with existing IDs do not edit or relocate them. New IDs add genuinely present scene facts. For a new map ID, explicitly place every accompanying saved body/object by its exact ID. Existing dimensions, activity and mechanic metadata are retained; only actual destination position, facing, plane and ambient lighting are admitted. Include active summons, carried/worn objects, and a live Mage Hand with its cargo and caster. Arena replacement is unavailable while an anchored object, wall panel including permanent Stone, retained coordinate area/terrain or anchored light needs its current scene. Those effects are preserved and the operation clearly rejects before initiative; do not remove them or substitute a different map ID to bypass this limit. Exploration does not require map movement.
arguments: {
 combat_scenes?: object[] // min items 0; max items 1
 // Exact state entity ID for first_actor from SYLVIA_GM_CAMPAIGN_PREPARATION or SYLVIA_GM_FRESH_CAMPAIGN_STATE; never use a display name.
 first_actor: string // a entity id
 // True only when the first creature was unaware that combat was starting. Use false for a creature that declares the attack or is already watching, threatening, or ready to act.
 first_surprised: boolean
 known_spell_effect?: boolean
 // Exact state entity ID for second_actor from SYLVIA_GM_CAMPAIGN_PREPARATION or SYLVIA_GM_FRESH_CAMPAIGN_STATE; never use a display name.
 second_actor: string // a entity id
 // True only when the second creature was unaware that combat was starting. Use false for a creature that is already watching, threatening, or ready to act.
 second_surprised: boolean
 tie_winner: "first" | "second"
 // Monk combatants choosing Uncanny Metabolism when Initiative is rolled: regain all Focus and heal Monk level plus the Martial Arts die, once per Long Rest. Leave empty to decline; eligible level-15 Monks then receive Perfect Focus automatically.
 uncanny_metabolism_users?: string[] // min items 0; max items 16; unique
 // Declare what remains of the exact current player request after this preparation succeeds. Use unresolved_action if an attack or other action was declared and still needs resolution; omission has that same meaning. Use await_player_choice only when the request ends at preparation, such as establishing Initiative before the player chooses an action. Never use it to abandon an already-declared action or invent the player's next choice. This is provider-only control, not a Ruleset or Campaign State field.
 player_intent_after_preparation?: "unresolved_action" | "await_player_choice"
}

## activate_srd_weapon_set
Switch a prepared weapon set freely on this creature's own turn. Switching never restores an Action, attack, Light/Nick use or other resource.
arguments: {
 // Exact state entity ID for actor_state from SYLVIA_GM_CAMPAIGN_PREPARATION or SYLVIA_GM_FRESH_CAMPAIGN_STATE; never use a display name.
 actor_state: string // a entity id
 // Exact state entity ID for lasting_state from SYLVIA_GM_CAMPAIGN_PREPARATION or SYLVIA_GM_FRESH_CAMPAIGN_STATE; never use a display name.
 lasting_state?: string // a entity id
 set_name: "melee" | "ranged"
}

## advance_stable_recovery
Advance the official 1d4-hour recovery clock for a Stable creature at 0 Hit Points.
arguments: {
 elapsed_hours: integer
 known_spell_effect?: boolean
 // Exact state entity ID for target from SYLVIA_GM_CAMPAIGN_PREPARATION or SYLVIA_GM_FRESH_CAMPAIGN_STATE; never use a display name.
 target: string // a entity id
 witness_state_ids?: string[]
}

## record_srd_creature_relationship
Record the scene's creature relationship used by hostility and witnessed-ally consequences.
arguments: {
 // Exact state entity ID for actor_state from SYLVIA_GM_CAMPAIGN_PREPARATION or SYLVIA_GM_FRESH_CAMPAIGN_STATE; never use a display name.
 actor_state: string // a entity id
 attitude: "hostile" | "indifferent" | "friendly"
 is_ally?: boolean
 // Exact state entity ID for toward_state from SYLVIA_GM_CAMPAIGN_PREPARATION or SYLVIA_GM_FRESH_CAMPAIGN_STATE; never use a display name.
 toward_state: string // a entity id
}

## record_srd_soul_disposition
Record the actual individual's free and willing soul facts without asserting death or revival.
arguments: {
 free: boolean
 // Exact state entity ID for target_state from SYLVIA_GM_CAMPAIGN_PREPARATION or SYLVIA_GM_FRESH_CAMPAIGN_STATE; never use a display name.
 target_state: string // a entity id
 willing: boolean
}

## record_srd_earth_material
Record actual natural dirt, sand or clay for one existing terrain identity.
arguments: {
 geometry_id: string
 material: "dirt" | "sand" | "clay"
}

## award_srd_advancement
Record a Plan milestone or allocated XP award once for this character. Read the policy and verify its trigger, timing and recipients first. Repeat for every eligible party member when the policy awards the whole party. An award does not apply a level or resolve player choices.
arguments: {
 // Stable milestone ID, or unique XP event ID.
 award_id: string
 // Exact participant_id for character from SYLVIA_GM_CAMPAIGN_PREPARATION or SYLVIA_GM_FRESH_CAMPAIGN_STATE; never use a display name.
 character: string // a participant id
 // The same character ID, selecting its live mechanical state.
 character_state: string // a entity id
 // Played event satisfying the policy, including allocation.
 evidence: string
 // Allocated XP for this character; 0 for milestones.
 xp: integer // >= 0
}

## record_srd_object_holder
Admit the actual creature carrying or wearing this scene object outside combat.
arguments: {
 // Exact state entity ID for actor_state from SYLVIA_GM_CAMPAIGN_PREPARATION or SYLVIA_GM_FRESH_CAMPAIGN_STATE; never use a display name.
 actor_state: string // a entity id
 held_as: "carried" | "worn"
 known_spell_effect?: boolean
 object_id: string
}

## dismiss_srd_senses_spell
Dismiss only this caster's saved time-span senses spell without spending an action. An Incapacitated caster cannot dismiss it. Native senses and other casters' grants remain active.
arguments: {
 // Exact state entity ID for caster_state from SYLVIA_GM_CAMPAIGN_PREPARATION or SYLVIA_GM_FRESH_CAMPAIGN_STATE; never use a display name.
 caster_state: string // a entity id
 known_spell_effect?: boolean
 spell: string
}

## prepare_srd_creature
Prepare one new NPC or monster from a read Plan/Setting stat block, or an explicitly recorded GM adjudication, before starting combat. This creates authoritative creature state; narrative characters do not create it. Use one stable ID per individual. Existing identities and Player Characters/Companions are rejected without resetting them. Copy source defenses and any known save modifiers. This does not automate unencoded traits or an entire stat block. After success, start the intended encounter with this ID and the admitted party IDs before narrating its result. For spellcasters, copy the listed spells, casting statistics and per-day uses from the source. Zero uses_per_day means at will. Do not infer spell slots or cantrip scaling from Challenge Rating.
arguments: {
 // AC from the source or explicit GM adjudication.
 armor_class: integer // >= 1; <= 40
 // Default 1. Supply another level only when the stat block explicitly grants scaled cantrips; never substitute Challenge Rating.
 cantrip_scaling_level?: integer // >= 1; <= 20
 // The stat block's Challenge Rating multiplied by eight. Omit when unknown; transformation eligibility then cannot be asserted from this creature state.
 challenge_rating_eighths?: integer // >= 0; <= 240
 // Optional signed charisma saving-throw modifier. Supply the source value or explicitly adjudicate it; omission does not establish a zero modifier.
 charisma_save?: integer // >= -10; <= 30
 charisma_score?: integer // >= 1; <= 30
 // Optional signed constitution saving-throw modifier. Supply the source value or explicitly adjudicate it; omission does not establish a zero modifier.
 constitution_save?: integer // >= -10; <= 30
 constitution_score?: integer // >= 1; <= 30
 // Stable unique ID for this individual creature, at most 128 letters/digits or . _ : -. Reuse it later; never use a Player Character or Companion ID.
 creature_id: string // pattern "^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$(?![\\s\\S])"
 // Creature type from the selected stat block. Omit when unknown; type-qualified spell effects cannot infer it.
 creature_type?: "aberration" | "beast" | "celestial" | "construct" | "dragon" | "elemental" | "fey" | "fiend" | "giant" | "humanoid" | "monstrosity" | "ooze" | "plant" | "undead"
 // Copy all damage immunities from the source; an omitted list means none.
 damage_immunities?: ("acid" | "bludgeoning" | "cold" | "fire" | "force" | "lightning" | "necrotic" | "piercing" | "poison" | "psychic" | "radiant" | "slashing" | "thunder")[] // max items 13; unique
 // Copy all damage resistances from the source; an omitted list means none.
 damage_resistances?: ("acid" | "bludgeoning" | "cold" | "fire" | "force" | "lightning" | "necrotic" | "piercing" | "poison" | "psychic" | "radiant" | "slashing" | "thunder")[] // max items 13; unique
 // Copy all damage vulnerabilities from the source; an omitted list means none.
 damage_vulnerabilities?: ("acid" | "bludgeoning" | "cold" | "fire" | "force" | "lightning" | "necrotic" | "piercing" | "poison" | "psychic" | "radiant" | "slashing" | "thunder")[] // max items 13; unique
 // Optional signed dexterity saving-throw modifier. Supply the source value or explicitly adjudicate it; omission does not establish a zero modifier.
 dexterity_save?: integer // >= -10; <= 30
 dexterity_score?: integer // >= 1; <= 30
 // Optional one equipment profile from the stat block or recorded GM adaptation. Record base speeds before armor, AC without worn gear (including natural defenses), Strength/Dexterity, armor training, and zero or one carried item in armor/shield. Supplied final AC and walking Speed must agree. Omit only when gear changes are not needed.
 equipment?: ({
  armor: ({
   armor_type: "padded_armor" | "leather_armor" | "studded_leather_armor" | "hide_armor" | "chain_shirt" | "scale_mail" | "breastplate" | "half_plate_armor" | "ring_mail" | "chain_mail" | "splint_armor" | "plate_armor"
   inventory_item: string // min length 1
   magic_bonus: integer // >= 0; <= 3
  })[]
  armor_training: ("light" | "medium" | "heavy" | "shield")[] // unique
  climb_speed: integer // >= 0; <= 1000
  dexterity: integer // >= 1; <= 30
  shield: {
   armor_type: "shield"
   inventory_item: string // min length 1
   magic_bonus: integer // >= 0; <= 3
  }[]
  speed: integer // >= 0; <= 1000
  strength: integer // >= 1; <= 30
  swim_speed: integer // >= 0; <= 1000
  unarmored_ac: integer // >= 1; <= 40
 })[] // max items 1
 // Copy actual native Flying Speed from the source; zero if none.
 flying_speed?: integer // >= 0; <= 1000
 // Current and maximum HP for this newly introduced, unwounded creature. Never prepare an existing wounded creature again.
 hit_points: integer // >= 1; <= 10000
 // Signed Initiative modifier from the source or explicit GM adjudication.
 initiative_modifier: integer // >= -10; <= 20
 // Optional signed intelligence saving-throw modifier. Supply the source value or explicitly adjudicate it; omission does not establish a zero modifier.
 intelligence_save?: integer // >= -10; <= 30
 intelligence_score?: integer // >= 1; <= 30
 inventory?: string[] // unique
 melee_reach?: integer // >= 0; <= 100
 // Optional pure-attack Multiattack routine from the read stat block or explicit recorded adaptation. Each attack name is unique, at most 120 characters, and names one component with its permitted count. This does not encode spell substitutions or other non-attack effects.
 multiattack?: {
  attack: string // min length 1
  count: integer // >= 1; <= 10
 }[] // max items 8
 // Creature display name, 1 to 120 characters.
 name: string // min length 1; max length 120
 native_hit_dice_count?: integer // >= 1; <= 1000
 native_hit_die_size?: integer // >= 4; <= 20
 // Actual stat-block Proficiency Bonus when a spell-created creature inherits it.
 proficiency_bonus?: integer // >= 2; <= 9
 // Copy the explicit complete proficiency list from the source. Omission leaves training unknown; an empty list explicitly records none.
 saving_throw_proficiencies?: ("strength" | "dexterity" | "constitution" | "intelligence" | "wisdom" | "charisma")[] // max items 6; unique
 // Size from the source or recorded adjudication: Tiny 0, Small 1, Medium 2, Large 3, Huge 4, Gargantuan 5.
 size_rank: integer // >= 0; <= 5
 // Actual total NPC skill-check modifiers from the selected stat block. For an unlisted skill use its actual ability modifier. Omitted skills remain unknown; never guess them from saving throws.
 skill_checks?: ({
  modifier: integer // >= -10; <= 30
  skill: "acrobatics" | "animal_handling" | "arcana" | "athletics" | "deception" | "history" | "insight" | "intimidation" | "investigation" | "medicine" | "nature" | "perception" | "performance" | "persuasion" | "religion" | "sleight_of_hand" | "stealth" | "survival"
 })[] // max items 18
 // Copy the explicit complete proficiency list from the source. Omission leaves training unknown; an empty list explicitly records none.
 skill_proficiencies?: ("athletics" | "acrobatics" | "sleight_of_hand" | "stealth" | "arcana" | "history" | "investigation" | "nature" | "religion" | "animal_handling" | "insight" | "medicine" | "perception" | "survival" | "deception" | "intimidation" | "performance" | "persuasion")[] // max items 18; unique
 // 1 to 1000 characters: identify the read Plan/Setting/stat-block reference and explicitly explain any GM-adjudicated adaptation or missing statistics.
 source: string // min length 1; max length 1000
 // Walking speed in feet from the source or explicit GM adjudication.
 speed: integer // >= 0; <= 1000
 spell_attack_bonus?: integer // >= -5; <= 30
 // Copy only components explicitly waived by this creature stat block. Empty means normal spell components are required; do not infer a waiver from slot-free casting.
 spell_component_exemptions?: ("verbal" | "somatic" | "material")[] // max items 3; unique
 spell_materials?: ({
  components: string[] // unique
  id: string
  inventory_item: string // min length 1
  kind: "specific" | "component_pouch" | "arcane_focus" | "druidic_focus" | "holy_symbol" | "musical_instrument"
  quantity: integer // >= 0; <= 1000000
  value_cp: integer // >= 0; <= 1000000000
 })[] // max items 128
 spell_save_dc?: integer // >= 1; <= 30
